if (points.empty()) {
    return Point_2(); // Return default-constructed point for empty input
}

auto traits = CGAL::Traits_2<Point_2>::type();
Point_2 leftmost = points[0];
typename std::vector<Point_2>::const_iterator w = points.begin();

for (auto it = points.begin(); it != points.end(); ++it) {
    if (traits.less_xy_2_object()(*it, leftmost)) {
        leftmost = *it;
    }
}
return leftmost;

